{"knowledge_entries":[
  {
    "intended_agents":["ocean_discovery_guide"],
    "name":"Überblick Ozeanwissen",
    "source_object_ids":["object_001","object_002","object_003"],
    "tag":"ozean_wissen",
    "text":"Der Raum ist in drei Sammlungen gegliedert: Meeresbewohner & Tauchfahrzeuge, Meeresströmungen & Tiefsee sowie Korallen & Plankton. Jede Zone enthält Exponate wie Shell Cases, Submersible Models, Strömungsdiagramme, Tiefenstationen, Korallenmodelle und Plankton-Displays, die zentrale Aspekte des Ozeans und seiner Erforschung vermitteln."
  },
  {
    "intended_agents":["ocean_discovery_guide"],
    "name":"Meeresbewohner entdecken",
    "source_object_ids":["object_001","object_007","object_013"],
    "tag":"meeresbewohner",
    "text":"In Sammlung 1 findest du Shell Cases, die verschiedene Meereslebewesen repräsentieren. Sie zeigen die Vielfalt der Ozeanfauna und geben Einblicke in Lebensräume wie Küsten, Tiefsee und Korallenriffe."
  },
  {
    "intended_agents":["ocean_discovery_guide"],
    "name":"Tiefsee und ihre Erforschung",
    "source_object_ids":["object_004","object_005","object_011"],
    "tag":"tiefsee",
    "text":"Die Tiefsee wird in Sammlung 2 durch Tiefenstationen und Submersible Models dargestellt. Diese Exponate zeigen, wie Forschende mit speziellen Technologien die unerforschten Bereiche des Ozeans erkunden."
  },
  {
    "intended_agents":["ocean_discovery_guide"],
    "name":"Forschungstechnologien im Ozean",
    "source_object_ids":["object_004","object_010","object_005"],
    "tag":"forschungstechnologien",
    "text":"Submersible Models und Tiefenstationen in Sammlung 1 und 2 veranschaulichen, wie moderne Technik wie Tauchroboter und Messstationen zur Erforschung von Ozeanen und Tiefsee eingesetzt werden."
  },
  {
    "intended_agents":["ocean_discovery_guide","ecosystem_expert"],
    "name":"Korallen – Lebensraum und Schutz",
    "source_object_ids":["object_003","object_009","object_015"],
    "tag":"korallen",
    "text":"Korallenmodelle in Sammlung 3 zeigen die Bedeutung von Korallenriffen als Lebensraum für zahlreiche Meeresbewohner und als Schutz für Küstenregionen."
  },
  {
    "intended_agents":["ocean_discovery_guide","ecosystem_expert"],
    "name":"Plankton – Basis des Ozeanlebens",
    "source_object_ids":["object_006","object_012"],
    "tag":"plankton",
    "text":"Plankton-Displays in Sammlung 3 verdeutlichen die Rolle von Plankton als Grundlage der Nahrungskette im Ozean und als Sauerstoffproduzent für das globale Klima."
  },
  {
    "intended_agents":["interactive_learning_assistant"],
    "name":"Quiz: Strömungen und Tiefsee",
    "source_object_ids":["object_002","object_005","object_008"],
    "tag":"quiz",
    "text":"Quizstationen bei Strömungsdiagrammen und Tiefenstationen in Sammlung 2 laden dazu ein, Wissen über Meeresströmungen und Tiefsee interaktiv zu testen."
  },
  {
    "intended_agents":["interactive_learning_assistant"],
    "name":"Lernerfahrung durch Exponate",
    "source_object_ids":["object_006","object_012"],
    "tag":"lernerfahrung",
    "text":"Plankton-Displays in Sammlung 3 bieten interaktive Elemente, die Besucher:innen zum Mitmachen und Entdecken der Bedeutung von Plankton im Ozean anregen."
  },
  {
    "intended_agents":["interactive_learning_assistant"],
    "name":"Vertiefung: Meeresströmungen",
    "source_object_ids":["object_008","object_014"],
    "tag":"vertiefung",
    "text":"Strömungsdiagramme in Sammlung 2 ermöglichen eine vertiefte Auseinandersetzung mit dem Einfluss von Meeresströmungen auf Klima und Lebensräume."
  },
  {
    "intended_agents":["interactive_learning_assistant"],
    "name":"Ozean interaktiv erleben",
    "source_object_ids":["object_005","object_006"],
    "tag":"ozean_interaktiv",
    "text":"Tiefenstationen und Plankton-Displays in den Sammlungen 2 und 3 bieten interaktive Möglichkeiten, um Ozeanprozesse und ökologische Zusammenhänge spielerisch zu erforschen."
  },
  {
    "intended_agents":["ecosystem_expert"],
    "name":"Ökosystem Ozean verstehen",
    "source_object_ids":["object_003","object_006","object_009"],
    "tag":"oekosystem_ozean",
    "text":"Korallenmodelle und Plankton-Displays in Sammlung 3 zeigen, wie Korallen und Plankton das Gleichgewicht und die Vielfalt im Ozean-Ökosystem sichern."
  },
  {
    "intended_agents":["ecosystem_expert"],
    "name":"Biodiversität im Ozean",
    "source_object_ids":["object_003","object_009","object_015"],
    "tag":"biodiversitaet",
    "text":"Die Korallenmodelle in Sammlung 3 verdeutlichen die hohe Artenvielfalt in Korallenriffen und deren Bedeutung für das gesamte Meeresleben."
  }
]}
